#!/usr/bin/env python3
"""Turn images generated by the partner service into traceable pixel-art assets.

The source images are intentionally kept untouched under assets/generated/bhai.
This script only creates derived PNGs under assets/sprites, assets/tilesets,
assets/ui, assets/effects, assets/objects, assets/items, and
assets/backgrounds.  It is deterministic so a later re-run produces the same
files.
"""

from __future__ import annotations

import argparse
import hashlib
import json
from collections import deque
from pathlib import Path

from PIL import Image


ROOT = Path(__file__).resolve().parents[1]
GENERATED = ROOT / "assets" / "generated" / "bhai"
SPRITES = ROOT / "assets" / "sprites"
TILESETS = ROOT / "assets" / "tilesets"
UI = ROOT / "assets" / "ui"
EFFECTS = ROOT / "assets" / "effects"
OBJECTS = ROOT / "assets" / "objects"
ITEMS = ROOT / "assets" / "items"
BACKGROUNDS = ROOT / "assets" / "backgrounds"
TRANSITIONS = ROOT / "assets" / "transitions"
INBOX = GENERATED / "inbox"


def ensure_dirs() -> None:
    for directory in (GENERATED, SPRITES, TILESETS, UI, EFFECTS, OBJECTS,
                      ITEMS, BACKGROUNDS, TRANSITIONS):
        directory.mkdir(parents=True, exist_ok=True)


def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def remove_checkerboard(image: Image.Image) -> Image.Image:
    """Remove the common white/light-gray checkerboard baked by image models.

    The model output is RGB, with nearly neutral alternating squares.  Pixels
    that are neutral and close to either checker tone become transparent.  A
    narrow feather is avoided deliberately: semi-transparent antialiased edges
    are harmful for nearest-neighbour pixel art.
    """

    rgba = image.convert("RGBA")
    pixels = rgba.load()
    width, height = rgba.size

    def is_checker_candidate(x: int, y: int) -> bool:
        r, g, b, _ = pixels[x, y]
        spread = max(r, g, b) - min(r, g, b)
        # The baked checker is neutral and light.  A flood from the image
        # border prevents neutral costume highlights/eyes from being removed.
        return spread <= 18 and ((r + g + b) // 3 >= 185)

    queue: deque[tuple[int, int]] = deque()
    seen: set[tuple[int, int]] = set()
    for x in range(width):
        for y in (0, height - 1):
            if is_checker_candidate(x, y):
                queue.append((x, y))
    for y in range(height):
        for x in (0, width - 1):
            if is_checker_candidate(x, y):
                queue.append((x, y))

    while queue:
        x, y = queue.popleft()
        if (x, y) in seen or not is_checker_candidate(x, y):
            continue
        seen.add((x, y))
        for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1),
                       (x - 1, y - 1), (x + 1, y - 1),
                       (x - 1, y + 1), (x + 1, y + 1)):
            if 0 <= nx < width and 0 <= ny < height and (nx, ny) not in seen:
                queue.append((nx, ny))
    for x, y in seen:
        pixels[x, y] = (0, 0, 0, 0)
    return rgba


def remove_dark_background(image: Image.Image) -> Image.Image:
    """Remove the near-black field used by some single-object generations.

    Only near-black pixels connected to the canvas border are removed.  Dark
    outlines inside the sprite therefore remain intact.
    """

    rgba = image.convert("RGBA")
    pixels = rgba.load()
    width, height = rgba.size

    def is_background(x: int, y: int) -> bool:
        r, g, b, _ = pixels[x, y]
        return max(r, g, b) <= 12

    queue: deque[tuple[int, int]] = deque()
    seen: set[tuple[int, int]] = set()
    for x in range(width):
        for y in (0, height - 1):
            if is_background(x, y):
                queue.append((x, y))
    for y in range(height):
        for x in (0, width - 1):
            if is_background(x, y):
                queue.append((x, y))

    while queue:
        x, y = queue.popleft()
        if (x, y) in seen or not is_background(x, y):
            continue
        seen.add((x, y))
        for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1),
                       (x - 1, y - 1), (x + 1, y - 1),
                       (x - 1, y + 1), (x + 1, y + 1)):
            if 0 <= nx < width and 0 <= ny < height and (nx, ny) not in seen:
                queue.append((nx, ny))
    for x, y in seen:
        pixels[x, y] = (0, 0, 0, 0)
    return rgba


def fit_single_asset(source: Path, destination: Path, size: int,
                     background: str = "checker", padding: int = 1,
                     align: str = "center", colors: int = 32) -> None:
    """Clean, trim and fit one generated object into a logical pixel canvas."""

    image = Image.open(source)
    if background == "checker":
        image = remove_checkerboard(image)
    elif background == "dark":
        image = remove_dark_background(image)
    else:
        image = image.convert("RGBA")

    alpha = image.getchannel("A").point(lambda value: 255 if value >= 128 else 0)
    image.putalpha(alpha)
    bounds = alpha.getbbox()
    if bounds is None:
        raise ValueError(f"{source} contains no foreground pixels")
    image = image.crop(bounds)

    available = size - 2 * padding
    scale = min(available / image.width, available / image.height)
    target_width = max(1, min(available, round(image.width * scale)))
    target_height = max(1, min(available, round(image.height * scale)))
    image = image.resize((target_width, target_height), Image.Resampling.BOX)

    alpha = image.getchannel("A").point(lambda value: 255 if value >= 128 else 0)
    opaque_rgb = Image.new("RGB", image.size, (0, 0, 0))
    opaque_rgb.paste(image.convert("RGB"), mask=alpha)
    image = opaque_rgb.quantize(colors=colors, method=Image.Quantize.MEDIANCUT).convert("RGBA")
    image.putalpha(alpha)

    canvas = Image.new("RGBA", (size, size), (0, 0, 0, 0))
    x = (size - target_width) // 2
    if align == "bottom":
        y = size - padding - target_height
    else:
        y = (size - target_height) // 2
    canvas.alpha_composite(image, (x, y))
    destination.parent.mkdir(parents=True, exist_ok=True)
    canvas.save(destination, "PNG", optimize=False)


