def make_directional_state_overrides() -> None:
    """Replace duplicated single-frame attempts with deterministic state art.

    The raw BHai files remain untouched under ``inbox/sprites`` for
    provenance.  The correction pass starts from the direction-specific idle
    cells in the reviewed runtime atlases, adds explicit hurt/death cues, and
    writes only the 24 runtime state files.  Keeping this call in the normal
    processing pipeline prevents a later ``--mvp-only`` rerun from silently
    restoring the rejected mirrored frames.
    """

    try:
        from generate_directional_states import generate
    except ImportError as exc:  # pragma: no cover - only reached outside repo
        raise RuntimeError("directional state generator is unavailable") from exc
    generate(SPRITES)


