def crop_cell_grid(source: Path, destination: Path, columns: int, rows: int,
                   frame_size: int, background: str = "checker",
                   resampling: Image.Resampling = Image.Resampling.BOX) -> None:
    """Crop an evenly generated grid, clean its background, and downsample."""

    image = Image.open(source)
    if image.width < columns or image.height < rows:
        raise ValueError(f"{source} is too small for {columns}x{rows}")
    cleaned = remove_checkerboard(image) if background == "checker" else image.convert("RGBA")
    cell_w = cleaned.width // columns
    cell_h = cleaned.height // rows
    atlas = Image.new("RGBA", (columns * frame_size, rows * frame_size), (0, 0, 0, 0))
    for row in range(rows):
        for column in range(columns):
            cell = cleaned.crop((column * cell_w, row * cell_h,
                                 (column + 1) * cell_w, (row + 1) * cell_h))
            # Keep the generated silhouette centred.  The source already has
            # generous padding, so a full-cell resize preserves the pivot.
            cell = cell.resize((frame_size, frame_size), resampling)
            # Quantize only after resizing, then restore alpha.  This reduces
            # accidental photographic colour noise while retaining the palette.
            # Generated sheets are RGB with a baked checkerboard.  A binary
            # alpha mask keeps the resulting atlas free of fringe pixels.
            opaque = cell.getchannel("A").point(lambda value: 255 if value >= 128 else 0)
            rgb = cell.convert("RGB").quantize(colors=32, method=Image.Quantize.MEDIANCUT)
            cell = rgb.convert("RGBA")
            cell.putalpha(opaque)
            atlas.alpha_composite(cell, (column * frame_size, row * frame_size))
    destination.parent.mkdir(parents=True, exist_ok=True)
    atlas.save(destination, "PNG", optimize=False)


def fit_effect_sheet(source: Path, destination: Path, frame_width: int,
                     frame_height: int, columns: int = 4,
                     padding: int = 1) -> None:
    """Clean a generated horizontal effect sheet into fixed-pivot frames.

    BHai returns a square 2K canvas even when the prompt requests a narrow
    horizontal sheet.  Each logical frame therefore occupies one vertical
    quarter of the source width, with generous checkerboard padding above and
    below the effect.  We trim each frame's foreground, use one scale derived
    from the largest frame so animation size stays stable, and place every
    frame around the same canvas centre.  The source remains untouched.
    """

    if not source.exists():
        return
    cleaned = remove_checkerboard(Image.open(source))
    cell_width = cleaned.width // columns
    bounds: list[tuple[int, int, int, int]] = []
    for column in range(columns):
        cell = cleaned.crop((column * cell_width, 0,
                             (column + 1) * cell_width, cleaned.height))
        bbox = cell.getchannel("A").point(
            lambda value: 255 if value >= 128 else 0
        ).getbbox()
        if bbox is None:
            raise ValueError(f"{source} frame {column} contains no foreground")
        bounds.append(bbox)

    available_width = max(1, frame_width - 2 * padding)
    available_height = max(1, frame_height - 2 * padding)
    max_width = max(bbox[2] - bbox[0] for bbox in bounds)
    max_height = max(bbox[3] - bbox[1] for bbox in bounds)
    scale = min(available_width / max_width,
                available_height / max_height)

    sheet = Image.new("RGBA", (frame_width * columns, frame_height),
                      (0, 0, 0, 0))
    for column, bbox in enumerate(bounds):
        cell = cleaned.crop((column * cell_width, 0,
                             (column + 1) * cell_width, cleaned.height))
        foreground = cell.crop(bbox)
        target_width = max(1, round(foreground.width * scale))
        target_height = max(1, round(foreground.height * scale))
        foreground = foreground.resize((target_width, target_height),
                                        Image.Resampling.BOX)
        alpha = foreground.getchannel("A").point(
            lambda value: 255 if value >= 128 else 0
        )
        foreground.putalpha(alpha)
        # Keep the model's limited palette but remove accidental colour noise
        # introduced by the 2K export.  Alpha is restored as a hard mask.
        rgb = foreground.convert("RGB").quantize(
            colors=32, method=Image.Quantize.MEDIANCUT
        ).convert("RGBA")
        rgb.putalpha(alpha)
        x = (frame_width - target_width) // 2
        y = (frame_height - target_height) // 2
        sheet.alpha_composite(rgb, (column * frame_width + x, y))

    destination.parent.mkdir(parents=True, exist_ok=True)
    sheet.save(destination, "PNG", optimize=False)


