def make_slug_death_down_placeholder() -> None:
    """Build the rejected down-death slot from the reviewed down idle.

    Build a deterministic fallback only when the partner-service down-death
    source is absent.  The runtime path deliberately matches the final asset
    so the scene does not need another code change when a reviewed source is
    promoted.
    """

    atlas = SPRITES / "spit_slug_sheet.png"
    if not atlas.exists():
        return
    try:
        from generate_directional_states import (
            apply_death,
            clean_components,
            extract_idle,
            reanchor,
        )
    except ImportError as exc:  # pragma: no cover - only reached outside repo
        raise RuntimeError("directional state generator is unavailable") from exc

    size = 32
    baseline = 30
    image = apply_death(
        extract_idle(atlas, size, 0, baseline),
        "down",
        baseline,
        "enemy",
        0,
    )
    clean_components(image, minimum_size=2)
    reanchor(image, baseline)
    clean_components(image, minimum_size=2)
    pixels = image.load()
    for y in range(size):
        for x in range(size):
            r, g, b, a = pixels[x, y]
            pixels[x, y] = (r, g, b, 255) if a else (0, 0, 0, 0)
    image.save(SPRITES / "spit_slug_death_down.png", "PNG", optimize=False)


