def make_repeated_boss_atlas(source: Path, destination: Path, frame_size: int = 64) -> None:
    """Derive a static 4x4 runtime atlas from a reviewed single-Boss image.

    The current upper-layer sources are single RGB images rather than the
    planned 4x4 sheets. Repeating the cleaned frame preserves the source art
    while keeping the existing directional/pose runtime contract intact.
    """
    temporary = destination.with_name(destination.stem + "_frame.png")
    fit_single_asset(source, temporary, frame_size, "checker", 2, "center", 48)
    frame = Image.open(temporary).convert("RGBA")
    atlas = Image.new("RGBA", (frame_size * 4, frame_size * 4), (0, 0, 0, 0))
    for row in range(4):
        for column in range(4):
            atlas.alpha_composite(frame, (column * frame_size, row * frame_size))
    destination.parent.mkdir(parents=True, exist_ok=True)
    atlas.save(destination, "PNG", optimize=False)
    temporary.unlink(missing_ok=True)


